        # 20% chance produce impossible (even t)
        even_ts = [x for x in range(2, n, 2)]
        if not even_ts:
            continue
        t = rng.choice(even_ts)
        return {'n': n, 'n_minus_one': n-1, 't': t}
# Final fallback (guaranteed valid and typically impossible)
n = 15
